/* ===========================================================
   Custom CSS for the DEFAULT (custom_format = 0) Print Format
   Paste this into: Print Format > CSS field
   Applies on top of Frappe's auto-generated layout — no HTML
   changes required.
   =========================================================== */

/* ---- Page & base typography ---- */
.print-format {
    font-family: "Helvetica Neue", Arial, sans-serif !important;
    font-size: 12px !important;
    color: #222 !important;
    line-height: 1.45 !important;
}

/* ---- Title / heading area (Company name, doc name) ---- */
.print-format .print-heading,
.print-format h2 {
    text-align: center !important;
    font-size: 18px !important;
    font-weight: 700 !important;
    color: #2c3e50 !important;
    margin-bottom: 2px !important;
    border: none !important;
}
.print-format .print-heading h6,
.print-format .print-heading small {
    text-align: center !important;
    color: #666 !important;
    font-size: 12px !important;
}

/* ---- Section labels (e.g. "Material Charges", "BOQ Summary") ---- */
.print-format .section-break > .section-head,
.print-format .section-head,
.print-format label.section-label {
    background: #2c3e50 !important;
    color: #fff !important;
    padding: 5px 8px !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.3px !important;
    display: block !important;
    margin: 14px 0 6px 0 !important;
    border-radius: 2px !important;
}

/* ---- Field label / value pairs in the header grid ---- */
.print-format .field-label,
.print-format td.label-area,
.print-format th.label-area {
    font-weight: 700 !important;
    color: #333 !important;
    white-space: nowrap !important;
}
.print-format .value,
.print-format td.value-area {
    color: #222 !important;
}

/* ---- All tables (child tables: material/freight/local/site/manpower/summary) ---- */
.print-format table {
    border-collapse: collapse !important;
    width: 100% !important;
    margin-bottom: 10px !important;
}
.print-format table th,
.print-format table td {
    border: 1px solid #cfd6dd !important;
    padding: 5px 7px !important;
    font-size: 11.5px !important;
}
.print-format table th {
    background: #eef1f4 !important;
    color: #2c3e50 !important;
    text-transform: uppercase !important;
    font-size: 10.5px !important;
    font-weight: 700 !important;
    text-align: left !important;
}

/* Right-align anything that looks numeric (qty/rate/amount columns) */
.print-format table td:nth-last-child(-n+3) {
    text-align: right !important;
    font-variant-numeric: tabular-nums !important;
}

/* Zebra striping for readability on long BOQ lists */
.print-format table tbody tr:nth-child(even) td {
    background: #f9fafb !important;
}

/* Bold the last row of each child table (commonly the totals/summary row) */
.print-format table tbody tr:last-child td {
    font-weight: 700 !important;
    background: #eef4ea !important;
    border-top: 2px solid #2c3e50 !important;
}

/* ---- Remove default heavy borders Frappe sometimes adds around sections ---- */
.print-format .col-xs-12,
.print-format .row {
    border: none !important;
}

/* ---- Footer / print info ---- */
.print-format .letter-head-footer,
.print-format .visible-pdf {
    font-size: 10px !important;
    color: #777 !important;
}

/* ---- Print media tweaks (avoid awkward page breaks mid-table) ---- */
@media print {
    .print-format table {
        page-break-inside: avoid !important;
    }
    .print-format .section-head {
        page-break-after: avoid !important;
    }
}
